export function itemFitsSlot(item,slot) {
 const types = {Head:1,Neck:2,Shoulder:3,Back:4,Chest:5,Wrist:6,Hands:7,Waist:8,Legs:9,Feet:10,"Finger 1":11,"Finger 2":11,"Trinket 1":12,"Trinket 2":12,Ranged:14};
 if (slot === "Main Hand") return item.type === 13 && [1,2,4].includes(item.handType);
 if (slot === "Off Hand") return item.type === 13 && [2,3].includes(item.handType);
 return types[slot] != null && item.type === types[slot];
}
